
































import { Component, Vue, Prop, PropSync } from "vue-property-decorator";

@Component({
  name: "RangeSlider"
})
export default class RangeSlider extends Vue {
  @Prop({ required: true }) private min!: number
  @Prop({ required: true }) private max!: number
  @Prop({ required: true }) private values!: object
  @PropSync('val', {required: true}) private value!: number

  private inputFocus = false
}
