import {
  IPriceCalculator,
  IPriceCalculatorData,
  IPriceCalculatorTooltipData,
  IPriceSettingsData
} from "@/api/type";
import {
  defaultPriceCalcData,
  defaultPriceSettingsData,
  defaultPriceSettingsTooltipData
} from "@/api/default";
import { request } from "@/utils/request";
import { tippy } from "vue-tippy";
import RangeSlider from "@/components/RangeSlider.vue";

@Component({
  components: {
    tippy,
    RangeSlider
  }
})
export default class App extends Vue {
  private calcData: IPriceSettingsData = defaultPriceCalcData;
  private data: IPriceCalculator = defaultPriceSettingsData;
  private promocode = "";
  private coefficientData: any;
  private valuteSelect = 0;
  private precentPromocode = 0;
  private priceStr: IPriceCalculatorTooltipData = defaultPriceSettingsTooltipData

  private contactData = {
    name: '',
    email: '',
    phone: '',
    message: '',
    sending: false
  }

  created() {
    this.calcData = (window as any).calcData;
    this.coefficientData = (window as any).coefficientData;
    this.priceStr = (window as any).priceStr;
  }

  private static priceSet(data: any) {
    const price = Number.prototype.toFixed.call(parseFloat(data) || 0, 2);
    return price
      .replace(/(\D)/g, ".")
      .replace(/(\d)(?=(\d{3})+(?!\d))/g, "$1 ");
  }

  private caclulatePrice() {
    let result = 0
    result += this.calcData.calculatorData.exteriorData.view[this.data.exterior.complexity] * this.data.exterior.view
    result += this.calcData.calculatorData.exteriorData.vr360[this.data.exterior.complexity] * this.data.exterior.vr360

    result += this.calcData.calculatorData.interiorData.view[this.data.interior.complexity] * this.data.interior.view
    result += this.calcData.calculatorData.interiorData.vr360[this.data.interior.complexity] * this.data.interior.vr360

    let precent = 0
    this.calcData.discountList.forEach(function (v) {
      if(result >= v.price && precent < v.precent) {
        precent = v.precent
      }
    })

    if(this.valuteSelect === 1)
      result *= this.coefficientData.EUR
    if(this.valuteSelect === 2)
      result *= this.coefficientData.GBP

    if(this.precentPromocode > 0)
      precent += this.precentPromocode
    if(precent > 0)
      result -= result * (precent / 100)

    return App.priceSet(result);
  }

  private promocodeUpdate() {
    request("post", "/promocode", { promocode: this.promocode }).then(e => {
      if (e.ok) {
        this.precentPromocode = +e.data;
      }
    });
  }

  submitContactForm(ev: Event) {
    ev.preventDefault()
    if(this.contactData.email.length < 3 || this.contactData.message.length < 10) {
      return
    }

    request("post", "/contact-form", this.contactData).then(e => {
      this.contactData.sending = true
      console.log(e)
    });
  }
}
